function validate([nums, k]) {
  const n = nums.length;
  if (n < 1 || n > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each nums[i] is an integer from 0 to nums.length - 1.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  return null;
}

