function minCost(nums, k) {
  // Try every set of cut positions and price each piece from scratch.
  const n = nums.length;
  const price = (piece) => {
    const freq = new Map();
    for (const v of piece) freq.set(v, (freq.get(v) || 0) + 1);
    let kept = 0;
    for (const c of freq.values()) if (c > 1) kept += c;
    return k + kept;
  };
  let best = Infinity;
  for (let mask = 0; mask < 1 << (n - 1); mask++) {
    let total = 0;
    let begin = 0;
    for (let i = 1; i <= n; i++) {
      if (i === n || (mask >> (i - 1)) & 1) {
        total += price(nums.slice(begin, i));
        begin = i;
      }
    }
    best = Math.min(best, total);
  }
  return best;
}

