function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 1000 : pick(1, 9);
  const distinct = rand() < 0.5 ? pick(1, Math.min(n, 4)) : n;
  const nums = Array.from({ length: n }, () => pick(0, distinct - 1));
  const roll = rand();
  const k = roll < 0.4 ? pick(1, 3) : roll < 0.8 ? pick(1, size === 'large' ? 60 : 8) : pick(1, 1000000000);
  return [nums, k];
}
